function activeCustomerValue(customers, orders){
  // sum lifetime_value of customers who have >= 1 order, each once
  let total = 0;
  for (const c of customers){
    for (const o of orders){
      if (o.customer_id === c.id){
        total += c.lifetime_value;   // adds once per matching order
      }
    }
  }
  return total;
}
this.activeCustomerValue = activeCustomerValue;

